func TestCeremony_Run(t *testing.T) {
	env := testenv.MustNew(
		testenv.WithAutoCreateDevice(true),
	)
	defer env.Close()

	devices := env.DevicesClient
	ctx := context.Background()

	macOSDev1, err := testenv.NewFakeMacOSDevice()
	require.NoError(t, err, "NewFakeMacOSDevice failed")
	windowsDev1 := testenv.NewFakeWindowsDevice()

	tests := []struct {
		name            string
		dev             testenv.FakeDevice
		assertErr       func(t *testing.T, err error)
		assertGotDevice func(t *testing.T, device *devicepb.Device)
	}{
		{
			name: "macOS device succeeds",
			dev:  macOSDev1,
			assertErr: func(t *testing.T, err error) {
				assert.NoError(t, err, "RunCeremony returned an error")
			},
			assertGotDevice: func(t *testing.T, d *devicepb.Device) {
				assert.NotNil(t, d, "RunCeremony returned nil device")
			},
		},
		{
			name: "windows device succeeds",
			dev:  windowsDev1,
			assertErr: func(t *testing.T, err error) {
				assert.NoError(t, err, "RunCeremony returned an error")
			},
			assertGotDevice: func(t *testing.T, d *devicepb.Device) {
				require.NotNil(t, d, "RunCeremony returned nil device")
				require.NotNil(t, d.Credential, "device credential is nil")
			printEnrollOutcome(enroll.DeviceEnrolled, dev)
		}
		return trace.Wrap(err)
	}))
}

func printEnrollOutcome(outcome enroll.RunAdminOutcome, dev *devicepb.Device) {
	var action string
	switch outcome {
	case enroll.DeviceRegisteredAndEnrolled:
		action = "registered and enrolled"
	case enroll.DeviceRegistered:
		action = "registered"
	case enroll.DeviceEnrolled:
		action = "enrolled"
	default:
		return // All actions failed, don't print anything.
	}

	if dev == nil {
		fmt.Printf("Device %v\n", action)
		return
	}
	fmt.Printf(
		"Device %q/%v %v\n",
		dev.AssetTag, devicetrust.FriendlyOSType(dev.OsType), action)
}

