func TestPrintEnrollOutcomeWithoutDevice(t *testing.T) {
	reader, writer, err := os.Pipe()
	require.NoError(t, err)
	defer reader.Close()
	defer writer.Close()

	stdout := os.Stdout
	os.Stdout = writer
	defer func() { os.Stdout = stdout }()

	printEnrollOutcome(enroll.DeviceRegistered, nil)
	os.Stdout = stdout
	require.NoError(t, writer.Close())
	output, err := io.ReadAll(reader)
	require.NoError(t, err)
	require.Equal(t, "Device registered\n", string(output))
}
